def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def as_pos(v):
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c"), ("i", "j")):
                if a in v and b in v and is_num(v.get(a)) and is_num(v.get(b)):
                    return [int(v.get(a)), int(v.get(b))]
            if "pos" in v:
                p = as_pos(v.get("pos"))
                if p is not None:
                    return p
            if "position" in v:
                p = as_pos(v.get("position"))
                if p is not None:
                    return p
        elif isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clip_move(dx, dy):
        if dx < -1: dx = -1
        if dx > 1: dx = 1
        if dy < -1: dy = -1
        if dy > 1: dy = 1
        return [dx, dy]

    def get_all_positions(v, out, depth=0):
        if depth > 4:
            return
        p = as_pos(v)
        if p is not None:
            out.append(p)
            return
        if isinstance(v, dict):
            for k in v:
                get_all_positions(v.get(k), out, depth + 1)
        elif isinstance(v, (list, tuple)):
            for item in v:
                get_all_positions(item, out, depth + 1)

    def find_pos_from_keys(d, keys):
        if not isinstance(d, dict):
            return None
        for k in keys:
            p = as_pos(d.get(k))
            if p is not None:
                return p
        return None

    obs = observation if isinstance(observation, dict) else {}
    me = find_pos_from_keys(obs, ("self", "agent", "player", "myself", "me", "position", "pos", "agent_pos", "player_pos"))
    if me is None:
        me = [0, 0]

    resources = []
    enemies = []
    allies = []
    targets = []

    for k in ("resources", "resource", "resource_positions", "food", "coins", "items", "goal", "goals", "targets", "target_positions"):
        get_all_positions(obs.get(k), resources if "resource" in k or k in ("food", "coins", "items") else targets)

    for k in ("enemies", "enemy_positions", "opponents", "opponent_positions", "pursuers", "predators", "threats", "agents"):
        get_all_positions(obs.get(k), enemies)

    for k in ("allies", "teammates", "friends"):
        get_all_positions(obs.get(k), allies)

    # Normalize and de-duplicate
    def unique(lst):
        seen = set()
        out = []
        for p in lst:
            t = (p[0], p[1])
            if t not in seen:
                seen.add(t)
                out.append(p)
        return out

    resources = unique(resources)
    enemies = unique(enemies)
    allies = unique(allies)
    targets = unique(targets)

    # Map / bounds inference
    width = None
    height = None
    grid = obs.get("grid", obs.get("map", obs.get("board")))
    if isinstance(grid, (list, tuple)) and grid:
        height = len(grid)
        if isinstance(grid[0], (list, tuple)):
            width = len(grid[0])

    bounds = obs.get("bounds")
    if isinstance(bounds, dict):
        width = bounds.get("width", width)
        height = bounds.get("height", height)
    elif isinstance(bounds, (list, tuple)) and len(bounds) >= 2:
        if is_num(bounds[0]) and is_num(bounds[1]):
            width = int(bounds[0])
            height = int(bounds[1])

    legal = obs.get("legal_moves")
    candidates = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if legal is not None:
                ok = False
                for lm in legal if isinstance(legal, (list, tuple)) else []:
                    p = as_pos(lm)
                    if p is not None and p[0] == dx and p[1] == dy:
                        ok = True
                        break
                    if isinstance(lm, dict):
                        if lm.get("dx") == dx and lm.get("dy") == dy:
                            ok = True
                            break
                if not ok:
                    continue
            candidates.append((dx, dy))

    if not candidates:
        candidates = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    # Heuristic scoring
    center = None
    if width is not None and height is not None:
        center = [width // 2, height // 2]

    threat_near = False
    min_enemy_dist = 999999
    for e in enemies:
        d = manhattan(me, e)
        if d < min_enemy_dist:
            min_enemy_dist = d
        if d <= 3:
            threat_near = True

    have_resources = len(resources) > 0
    have_targets = len(targets) > 0

    best_move = [0, 0]
    best_score = None

    for dx, dy in candidates:
        nx = me[0] + dx
        ny = me[1] + dy
        score = 0.0

        # Small preference for movement over waiting
        if dx == 0 and dy == 0:
            score -= 0.15

        # Avoid edges if bounds known
        if width is not None and height is not None:
            edge_pen = 0
            if nx <= 0 or nx >= width - 1:
                edge_pen += 0.2
            if ny <= 0 or ny >= height - 1:
                edge_pen += 0.2
            score -= edge_pen

        # Resource attraction
        if have_resources:
            dmin = 999999
            for r in resources:
                d = abs(nx - r[0]) + abs(ny - r[1])
                if d < dmin:
                    dmin = d
            score += 4.0 / (dmin + 1.0)

        # Generic target attraction
        if have_targets:
            dmin = 999999
            for t in targets:
                d = abs(nx - t[0]) + abs(ny - t[1])
                if d < dmin:
                    dmin = d
            score += 1.5 / (dmin + 1.0)

        # Enemy avoidance
        if enemies:
            close = 0.0
            for e in enemies:
                d = abs(nx - e[0]) + abs(ny - e[1])
                close += 1.0 / (d + 1.0)
            score -= 3.0 * close
            if threat_near:
                # stronger evasion when threatened
                score -= 0.5 / (min(abs(nx - enemies[0][0]) + abs(ny - enemies[0][1]), 10) + 1.0)

        # Center bias for territory control / exploration
        if center is not None:
            score += 0.6 / (abs(nx - center[0]) + abs(ny - center[1]) + 1.0)

        # If no resources and enemies exist, bias away from enemy centroid
        if not have_resources and enemies:
            cx = 0
            cy = 0
            for e in enemies:
                cx += e[0]
                cy += e[1]
            cx /= float(len(enemies))
            cy /= float(len(enemies))
            score += 1.0 * (abs(nx - cx) + abs(ny - cy)) / 10.0

        # Mild inertia: prefer continuing direction if any
        if "last_move" in obs:
            lm = as_pos(obs.get("last_move"))
            if lm is not None and lm[0] == dx and lm[1] == dy:
                score += 0.05

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < (best_move[0], best_move[1])):
            best_score = score
            best_move = [dx, dy]

    return clip_move(best_move[0], best_move[1])

